def kth_smallest_gap(positions, k):
    p = sorted(positions)
    n = len(p)

    def pairs_within(d):  # pairs at most d apart
        count = left = 0
        for right in range(n):
            while p[right] - p[left] > d:
                left += 1
            count += right - left
        return count

    lo, hi = 0, p[-1] - p[0]
    while lo < hi:
        mid = (lo + hi) // 2
        if pairs_within(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

